def tool_funcs(node):
    for child in ast.walk(node):
        if isinstance(child, ast.AsyncFunctionDef) and child.name in ("issue_create", "issue_update", "issue_add_comment", "issue_move"):
            yield child

for fn in tool_funcs(tree):
    declared = {a.arg for a in fn.args.args if a.arg not in ("ctx",)} | {a.arg for a in fn.args.kwonlyargs}
    forwarded = set()
    for node in ast.walk(fn):
        if isinstance(node, ast.Call):
            for kw in node.keywords:
                if kw.arg and isinstance(kw.value, ast.Name):
